//! 用户音量设置必须进入计划：BGM 按 `bgmVolume`，语音按 `vocalVolume`。

use std::fs;
use std::path::Path;

use webgal_video_export::api::{ExportOptions, build_plan};
use webgal_video_export::plan::AudioKind;

fn write(root: &Path, relative: &str, bytes: &[u8]) {
    let path = root.join(relative);
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).expect("create dir");
    }
    fs::write(path, bytes).expect("write fixture");
}

#[test]
fn bgm_and_vocal_apply_the_user_volume() {
    let directory = tempfile::tempdir().expect("temp dir");
    let root = directory.path();
    write(root, "game/config.txt", b"Game_name:Volume;\n");
    write(root, "game/bgm/theme.wav", b"RIFF");
    write(root, "game/vocal/theme.wav", b"RIFF");
    write(
        root,
        "game/scene/start.txt",
        b"bgm:theme.wav -volume=50;\nsay:hello -vocal=theme.wav;\nend;\n",
    );

    let mut options = ExportOptions::new(root);
    options.config.bgm_volume = 80;
    options.config.vocal_volume = 60;
    let plan = build_plan(&options).expect("build plan");

    let bgm = plan
        .audio
        .iter()
        .find(|event| event.kind == AudioKind::Bgm)
        .expect("BGM 事件");
    assert!((bgm.volume - 0.4).abs() < 1e-6, "BGM 音量: {}", bgm.volume);

    let vocal = plan
        .audio
        .iter()
        .find(|event| event.kind == AudioKind::Vocal)
        .expect("语音事件");
    assert!(
        (vocal.volume - 0.6).abs() < 1e-6,
        "语音音量: {}",
        vocal.volume
    );
}
